"""Generate bundled book palettes and Lucide catalog. No network or database access."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
# key, label, light cover/spine/bookmark/ink/pages, dark counterparts
PALETTES = [
 ('butter','鹅黄',['#FFF2B7','#F6D76F','#E8BA42','#A47B18','#FFFAE5'],['#3C3424','#514329','#CDA654','#E7C875','#655A42']),
 ('apricot','杏桃',['#FFDAC3','#F2B78F','#E69360','#B56C43','#FFF3EA'],['#402F29','#563B2E','#CC9067','#E9AD85','#665047']),
 ('coral','珊瑚',['#FFD2CD','#EEAAA4','#DF7D75','#AD5751','#FFF0EE'],['#402A2B','#563637','#CD827A','#E7A39A','#684A4B']),
 ('rose','玫瑰',['#F7D5E3','#E9ACC6','#D984AA','#A4577E','#FFF0F6'],['#3B2B35','#503747','#C382A5','#DFA5C3','#624B59']),
 ('lilac','丁香',['#E7DDF8','#C9B6EA','#AD91D8','#80639E','#F7F3FF'],['#332D41','#443953','#AC95CD','#C8B1E4','#554D65']),
 ('iris','鸢尾',['#DDDEF8','#B6B9E8','#9096D5','#626AA0','#F2F3FF'],['#2C3041','#3B4055','#909CCF','#B5BFE6','#4D566A']),
 ('mist','雾蓝',['#D8EAF9','#ACCEE9','#7FB1D6','#4F83AC','#F1F9FF'],['#273642','#324957','#7EAACD','#A3CCE7','#485E6D']),
 ('lagoon','湖青',['#D2EEEF','#A0D6D9','#70BABE','#438B90','#EEFCFC'],['#263A3D','#304E51','#74B9BD','#9DD4D7','#46646A']),
 ('mint','薄荷',['#D9F1E6','#ACDBC8','#7DBFA5','#4E9379','#F1FDF7'],['#293B33','#365044','#7FBAA1','#A4D7BE','#4B6858']),
 ('sage','鼠尾草',['#E4ECCD','#C3D29E','#A1B777','#738B4D','#F7FAED'],['#333A28','#454D34','#A5B57C','#C5D19D','#5B6548']),
 ('oat','燕麦',['#EEE2D2','#D7C3A9','#BDA17C','#8F7353','#FAF6EF'],['#39332C','#4B4136','#B59A79','#D2B99A','#62584A']),
 ('graphite','石墨',['#E1E6EB','#BCC6D0','#98A8B8','#667B8F','#F5F7FA'],['#2D333A','#3C454F','#91A5B9','#B4C5D6','#515D6A'])]
media=ROOT/'entry/src/main/resources/base/media'
keys=sorted(p.stem for p in media.glob('lucide_*.svg'))
preferred=['lucide_notebook_text1','lucide_house1','lucide_wallet1','lucide_plane1','lucide_shopping_bag1','lucide_coffee1','lucide_heart1','lucide_graduation_cap1','lucide_car1','lucide_briefcase_business1','lucide_piggy_bank1','lucide_gift1']
keys=[k for k in preferred if k in keys]+[k for k in keys if k not in preferred]
model='// Generated by tools/generate-book-covers.py; do not edit by hand.\nexport interface BookPalette { key: string; name: string; light: string[]; dark: string[]; }\nexport const BOOK_PALETTES: BookPalette[] = [\n'
model+=',\n'.join('  { key: '+json.dumps(k)+', name: '+json.dumps(n,ensure_ascii=False)+', light: '+json.dumps(l)+', dark: '+json.dumps(d)+' }' for k,n,l,d in PALETTES)+'\n];\n'
model+='export const BOOK_ICON_KEYS: string[] = '+json.dumps(keys,indent=2)+';\n'
(ROOT/'entry/src/main/ets/domain/model/BookCoverCatalog.ets').write_text(model)
roles=['cover','spine','accent','ink','pages']
for theme in ['base','dark']:
 p=ROOT/f'entry/src/main/resources/{theme}/element/color.json';data=json.loads(p.read_text());data['color']=[x for x in data['color'] if not x['name'].startswith('xq_book_cover_')]
 for k,n,l,d in PALETTES:
  for role,value in zip(roles,l if theme=='base' else d):data['color'].append({'name':f'xq_book_cover_{k}_{role}','value':value})
 p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
resource='// Generated by tools/generate-book-covers.py; do not edit by hand.\nexport interface BookCoverColors { key: string; '+ '; '.join(x+': Resource' for x in roles)+'; }\nexport const BOOK_COVER_COLORS: BookCoverColors[] = [\n'
resource+=',\n'.join("  { key: '"+k+"', "+', '.join(f"{role}: $r('app.color.xq_book_cover_{k}_{role}')" for role in roles)+' }' for k,*_ in PALETTES)+'\n];\n'
resource+='export interface BookIconChoice { key: string; resource: Resource; }\nexport const BOOK_ICON_CHOICES: BookIconChoice[] = [\n'+',\n'.join("  { key: '"+k+"', resource: $r('app.media."+k+"') }" for k in keys)+'\n];\n'
resource+='export function bookCoverColors(key: string): BookCoverColors { return BOOK_COVER_COLORS.find((item: BookCoverColors) => item.key === key) || BOOK_COVER_COLORS[0]; }\nexport function bookCoverIcon(key: string): Resource { return (BOOK_ICON_CHOICES.find((item: BookIconChoice) => item.key === key) || BOOK_ICON_CHOICES[0]).resource; }\n'
(ROOT/'entry/src/main/ets/presentation/books/BookCoverResources.ets').write_text(resource)
print(f'Generated {len(PALETTES)} paired palettes and {len(keys)} bundled Lucide icons.')
